using System.Text.Json;
using System.Text.Json.Nodes;
namespace RisingLands;
public static class BalloonTransportTests {
 static List<string> checks=new();
 static void Check(bool ok,string label){if(!ok)throw new InvalidDataException("FAIL balloon: "+label);checks.Add(label);Console.WriteLine("PASS balloon: "+label);}
 static void Until(Simulation s,Func<bool> done,int limit,string label){for(int i=0;i<limit&&!done();i++)s.Step();Check(done(),label);}
 static World Fixture(string root){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE07.ETA"));new VisualCatalog().Apply(w);int index=w.Buildings.FindIndex(b=>b.Owner==0&&b.Type==3);w.Buildings[index]=w.Buildings[index] with{Type=18};return w;}
 public static void Run(string root,string output){
  checks.Clear();var s=new Simulation(Fixture(root));Check(!s.IsEighthMission&&!s.World.Units.Any(a=>a.Type==17),"non-M8 fixture starts without balloon");s.Step();Check(s.World.Units.Count(a=>a.Owner==0&&a.Type==17)==1,"occupied heliport supplies balloon outside mission eight");var balloon=s.World.Units.First(a=>a.Owner==0&&a.Type==17);var farmer=s.World.Units.First(a=>a.Owner==0&&a.Type==5&&VisualCatalog.Visible(a));farmer.Food=1;s.World.Resources[0]--;int food=s.World.Resources[0],stone=s.World.Resources[4];
  Check(s.BoardBalloon(farmer,balloon),"farmer can be explicitly ordered aboard");var waiting=s.Serialize();s.Restore(waiting);Check(s.Serialize()==waiting,"manual waiting queue survives exact save");farmer=s.World.Units.First(a=>a.Slot==farmer.Slot);balloon=s.World.Units.First(a=>a.Slot==balloon.Slot);Until(s,()=>s.BalloonPassengers(balloon).Count==1,2000,"farmer walks to actual boarding point");Check(!VisualCatalog.Visible(farmer)&&farmer.Food==1,"onboard farmer hidden with load preserved");for(int i=0;i<120;i++)s.Step();Check(s.BalloonPassengers(balloon).Count==1,"manual passenger stays aboard awaiting flight order");var flight=s.Serialize();var loaded=new Simulation(Fixture(root));loaded.Restore(flight);Check(loaded.Serialize()==flight,"manual aboard state restores outside mission eight");
  Check(s.UnloadBalloon(balloon,farmer.Type)==1&&VisualCatalog.Visible(farmer)&&farmer.Food==1,"class button disembarks safely and keeps food");Check(s.World.Resources[0]==food&&s.World.Resources[4]==stone,"boarding and unloading do not charge resources");
  Check(s.BoardBalloon(farmer,balloon),"farmer reboards");Until(s,()=>s.BalloonPassengers(balloon).Count==1,2000,"second boarding finishes");int obstacle=Enumerable.Range(0,65536).Where(c=>(c&255)<s.World.Width&&(c>>8)<s.World.Height&&!s.Passable(c&255,c>>8)).OrderBy(c=>Math.Abs((c&255)-50)+Math.Abs((c>>8)-50)).First();Check(s.Order(balloon,obstacle&255,obstacle>>8),"loaded balloon can fly over impassable terrain without unloading");Until(s,()=>balloon.Route.Count==0,6000,"loaded flight reaches impassable waypoint");Check(s.BalloonPassengers(balloon).Count==1&&!s.CanUnloadBalloon(balloon),"blocked terrain preserves passengers and rejects unsafe unload");var over=s.Serialize();s.Restore(over);Check(s.Serialize()==over,"loaded waypoint save preserves airborne passenger");farmer=s.World.Units.First(a=>a.Slot==farmer.Slot);balloon=s.World.Units.First(a=>a.Slot==balloon.Slot);int target=Enumerable.Range(0,65536).Where(c=>s.Passable(c&255,c>>8)&&s.ConstructionGrass(c)&&s.BuildingAt(c)==null).OrderBy(c=>Math.Abs((c&255)-50)+Math.Abs((c>>8)-50)).First();Check(s.Order(balloon,target&255,target>>8),"loaded balloon accepts terrain movement and delivery");Check(!s.UnloadBalloon(balloon).Equals(1),"cannot disembark in mid-flight");Until(s,()=>!s.WaitingForFlight(farmer),6000,"manual flight reaches destination and unloads");Check(VisualCatalog.Visible(farmer)&&farmer.Food==1&&Math.Abs(farmer.X/1024-(target&255))<=5&&Math.Abs(farmer.Y/1024-(target>>8))<=5,"arrival is valid land near chosen destination");
  var stable=s.Serialize();var bad=JsonNode.Parse(stable)!;bad["Ocean"]!["Balloons"]![0]!["Owner"]=1;bool rejected=false;try{s.Restore(bad.ToJsonString());}catch(InvalidDataException){rejected=true;}Check(rejected&&s.Serialize()==stable,"invalid ownership rejected without partial load");Check(!Simulation.BalloonPassengerType(3)&&!Simulation.BalloonPassengerType(8)&&!Simulation.BalloonPassengerType(11)&&Simulation.BalloonPassengerType(9),"documented passenger restrictions exclude Killer Archer vehicles");
  s.Restart();s.Step();Check(s.World.Units.Count(a=>a.Owner==0&&a.Type==17)==1&&s.Ocean.Jobs.Count==0,"restart supplies one balloon and no old passengers");
  // Isolated five-place scenario: initial extra people belong only to this test fixture.
  var crowd=Fixture(root);var template=crowd.Units.First(a=>a.Owner==0&&a.Type==9&&a.LegacyState==7);for(int i=0;i<6;i++){var a=JsonSerializer.Deserialize<Actor>(JsonSerializer.Serialize(template))!;a.Slot=800+i;crowd.Units.Add(a);}s=new(crowd);s.Step();balloon=s.World.Units.First(a=>a.Owner==0&&a.Type==17);var people=s.World.Units.Where(a=>a.Slot is >=800 and <806).ToArray();foreach(var a in people.Take(5))Check(s.BoardBalloon(a,balloon),"manual seat reserved");Check(!s.BoardBalloon(people[5],balloon),"sixth manual passenger rejected with five seats reserved");Until(s,()=>s.BalloonPassengers(balloon).Count==5,3000,"five manual passengers board");Check(s.UnloadBalloon(balloon)==5&&s.Ocean.Jobs.Count==0&&people.Take(5).All(VisualCatalog.Visible),"all five passengers unload and release seats");
  File.WriteAllText(output,JsonSerializer.Serialize(new{Passed=true,Checks=checks.Count,Assertions=checks,Limit="Non-M8 heliport fixture and passenger crowd are isolated; manual UI campaign not performed."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("ALL BALLOON TESTS PASSED: "+checks.Count);
 }
}
